using System;using System.Data;using System.Drawing;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmAdminDashboard:StyledForm {
 FlowLayoutPanel cards=new FlowLayoutPanel{Dock=DockStyle.Top,Height=112,Padding=new Padding(12),BackColor=Color.White};DataGridView recent=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect};
 public FrmAdminDashboard(){Text="UCS Pyay Administration";WindowState=FormWindowState.Maximized;MinimumSize=new Size(1050,650);var side=new FlowLayoutPanel{Dock=DockStyle.Left,Width=220,FlowDirection=FlowDirection.TopDown,Padding=new Padding(18),BackColor=UiTheme.Navy,WrapContents=false,AutoScroll=true};side.Controls.Add(new Label{Text="UCS PYAY\r\nADMIN PORTAL",ForeColor=Color.White,Font=new Font("Segoe UI",16,FontStyle.Bold),Width=180,Height=60,TextAlign=ContentAlignment.MiddleLeft});Add(side,"Applications",delegate{OpenModule(new FrmApplications());});Add(side,"Student Management",delegate{OpenModule(new FrmStudentManagement());});Add(side,"Admission List",delegate{OpenModule(new FrmAdmissionList());});Add(side,"Semester Results",delegate{OpenModule(new FrmSemesterResults());});Add(side,"Documents / Verification",delegate{OpenModule(new FrmDataManagement("Documents"));});Add(side,"Payments",delegate{OpenModule(new FrmDataManagement("Payments"));});Add(side,"Refund Management",delegate{OpenModule(new FrmRefundManagement());});Add(side,"Reports & Export",delegate{OpenModule(new FrmReports());});Add(side,"Data Management",delegate{OpenModule(new FrmDataManagement());});Add(side,"System Settings",delegate{OpenModule(new FrmSystemSettings());});var logout=UiTheme.Secondary("Log Out");logout.Width=175;logout.Height=40;logout.Margin=new Padding(3,8,3,3);logout.Click+=delegate{Close();};side.Controls.Add(logout);var content=new Panel{Dock=DockStyle.Fill,Padding=new Padding(18)};content.Controls.Add(recent);content.Controls.Add(new Label{Text="Recent Applications",Dock=DockStyle.Top,Height=44,Font=new Font("Segoe UI",14,FontStyle.Bold),Padding=new Padding(5,8,0,0)});content.Controls.Add(cards);content.Controls.Add(UiTheme.Heading("Administration Dashboard","Registration overview and recent application activity"));Controls.Add(content);Controls.Add(side);recent.CellDoubleClick+=delegate{if(recent.CurrentRow!=null){new FrmApplicationDetails(Convert.ToInt32(recent.CurrentRow.Cells["ApplicationId"].Value)).ShowDialog(this);LoadDashboard();}};Activated+=delegate{LoadDashboard();};}
 void OpenModule(Form form){try{form.Show(this);form.BringToFront();}catch(Exception ex){form.Dispose();MessageBox.Show("This screen could not be opened.\r\n"+ex.Message,"Screen Error",MessageBoxButtons.OK,MessageBoxIcon.Error);}}void Add(Control p,string s,EventHandler e){var b=new Button{Text=s,Width=175,Height=36,Margin=new Padding(3,2,3,2),TextAlign=ContentAlignment.MiddleLeft,Padding=new Padding(15,0,0,0),BackColor=Color.FromArgb(28,91,143)};b.Click+=e;p.Controls.Add(b);}void LoadDashboard(){cards.Controls.Clear();DataTable t=new ApplicationQuery().All("");string[] labels={"Total","Submitted","Under Review","Needs Correction","Approved","Rejected"};Color[] colors={Color.FromArgb(42,112,157),Color.FromArgb(230,145,56),Color.FromArgb(91,141,184),Color.FromArgb(192,80,77),Color.FromArgb(72,142,79),Color.FromArgb(130,65,65)};for(int i=0;i<labels.Length;i++){string x=labels[i];int n=x=="Total"?t.Rows.Count:t.Select("Status='"+x.Replace("'","''")+"'").Length;cards.Controls.Add(new Label{Text=n+"\r\n"+x,Width=135,Height=75,Margin=new Padding(6),TextAlign=ContentAlignment.MiddleCenter,BackColor=colors[i],ForeColor=Color.White,Font=new Font("Segoe UI",11,FontStyle.Bold)});}recent.DataSource=t;if(recent.Columns.Contains("ApplicationId"))recent.Columns["ApplicationId"].Visible=false;}
} }
